package com.gerenciadorrural.modules.finance.api;
import com.fasterxml.jackson.annotation.JsonIgnoreProperties; import com.gerenciadorrural.modules.finance.application.FinanceService; import com.gerenciadorrural.modules.finance.domain.FinanceModels.*; import com.gerenciadorrural.modules.organizations.api.ResolvedTenantContext; import com.gerenciadorrural.shared.tenancy.TenantContext; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/finance") public class FinanceController {private final FinanceService s;public FinanceController(FinanceService s){this.s=s;}
 @PostMapping("/categories") ResponseEntity<Category> createCategory(@ResolvedTenantContext TenantContext c,@RequestBody CategoryCreate r){return ResponseEntity.status(HttpStatus.CREATED).body(s.createCategory(c,r.name,r.code,r.kind));}@GetMapping("/categories") List<Category> categories(@ResolvedTenantContext TenantContext c){return s.categories(c);}@GetMapping("/categories/{id}") Category category(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return s.category(c,id);}@PatchMapping("/categories/{id}") Category patchCategory(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody CategoryPatch r){return s.patchCategory(c,id,r.expectedVersion,r.name,r.nameSet,r.code,r.codeSet,r.kind,r.kindSet,r.status,r.statusSet);}
 @PostMapping("/entries") ResponseEntity<Entry> create(@ResolvedTenantContext TenantContext c,@RequestBody EntryCreate r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(c,r.operationId,r.type,r.categoryId,r.description,r.amount,r.dueOn,r.notes));}@GetMapping("/entries") FinanceService.Page<Entry> entries(@ResolvedTenantContext TenantContext c,@RequestParam(required=false)EntryType type,@RequestParam(required=false)EntryStatus status,@RequestParam(required=false)UUID categoryId,@RequestParam LocalDate dueFrom,@RequestParam LocalDate dueTo,@RequestParam(required=false)String search,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.entries(c,type,status,categoryId,dueFrom,dueTo,search,page,size);}@GetMapping("/entries/{id}") Entry entry(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return s.entry(c,id);}@PatchMapping("/entries/{id}") Entry patch(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody EntryPatch r){return s.patch(c,id,r.expectedVersion,r.categoryId,r.categoryIdSet,r.description,r.descriptionSet,r.amount,r.amountSet,r.dueOn,r.dueOnSet,r.notes,r.notesSet);}@PostMapping("/entries/{id}/settlement") Entry settlement(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody Settlement r){return s.settle(c,id,r.operationId,r.expectedVersion,r.settledOn);}@PostMapping("/entries/{id}/cancellation") Entry cancellation(@ResolvedTenantContext TenantContext c,@PathVariable UUID id,@RequestBody Cancellation r){return s.cancel(c,id,r.operationId,r.expectedVersion,r.reason);}@GetMapping("/entries/{id}/history") List<Event> history(@ResolvedTenantContext TenantContext c,@PathVariable UUID id){return s.history(c,id);}@GetMapping("/summary") Summary summary(@ResolvedTenantContext TenantContext c,@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(required=false)UUID categoryId){return s.summary(c,categoryId,from,to);}@GetMapping("/summary/by-category") List<CategoryTotals> categoryTotals(@ResolvedTenantContext TenantContext c,@RequestParam LocalDate from,@RequestParam LocalDate to){return s.categoryTotals(c,from,to);}
 @JsonIgnoreProperties(ignoreUnknown=false) public static class CategoryCreate{public String name,code;public CategoryKind kind;}@JsonIgnoreProperties(ignoreUnknown=false) public static class CategoryPatch{public Long expectedVersion;public String name,code;public CategoryKind kind;public CategoryStatus status;public boolean nameSet,codeSet,kindSet,statusSet;}@JsonIgnoreProperties(ignoreUnknown=false) public static class EntryCreate{public UUID operationId,categoryId;public EntryType type;public String description,notes;public BigDecimal amount;public LocalDate dueOn;}@JsonIgnoreProperties(ignoreUnknown=false) public static class EntryPatch{public Long expectedVersion;public UUID categoryId;public String description,notes;public BigDecimal amount;public LocalDate dueOn;public boolean categoryIdSet,descriptionSet,notesSet,amountSet,dueOnSet;}@JsonIgnoreProperties(ignoreUnknown=false) public static class Settlement{public UUID operationId;public Long expectedVersion;public LocalDate settledOn;}@JsonIgnoreProperties(ignoreUnknown=false) public static class Cancellation{public UUID operationId;public Long expectedVersion;public String reason;}}
